<script setup lang="ts">
import { computed, ref } from 'vue'
import { records, count, percent, date, state, sum, portrait, gradeNames, selectedStats } from '../data'
import Icon from '../components/Icon.vue'
defineProps<{ catalog?: boolean }>()
const search = ref(''), grade = ref('all'), filter = ref('all')
const covered = computed(() => records.value.filter(r => BigInt(r.observation_count) > 0n))
const latest = computed(() => records.value.map(r => r.latest_capture_at).filter((s): s is string => !!s).sort().at(-1))
const rows = computed(() => records.value.filter(r => r.name.includes(search.value.trim()) && (filter.value === 'all' || (filter.value === 'observed' ? BigInt(r.observation_count) > 0n : selectedStats(r, grade.value).win_rate !== null))))
</script>
<template>
  <section v-if="!catalog" class="hero">
    <div class="hero-copy"><div class="eyebrow"><span></span>百炼之间 · 万象可寻</div><h1>每一场胜负，<br/>都有值得读懂的故事。</h1><p>从百炼榜的细微变化，观察式神的表现。<br/>以真实样本为起点，让每一次选择多一份依据。</p><RouterLink to="/method" class="hero-link">了解统计方式 <Icon name="arrow" :size="17"/></RouterLink></div>
    <div class="hero-art" aria-hidden="true"><div class="art-moon"></div><div class="mountain mountain-back"></div><div class="mountain mountain-front"></div><svg class="ink-branch" viewBox="0 0 450 300"><path d="M410 295Q295 260 271 180T191 47M280 203Q337 174 359 111M263 151Q216 138 177 98M303 254Q356 252 423 205"/><path d="m193 50-35-13 27 23-32 2 39 8m161 48 34-21-24 32 30-8-39 22m-182-45-26-6 24 21m240 114 28-15-14 29"/></svg><span class="art-kanji">百<br/>闻</span><div class="art-stamp">百炼<br/>观测</div><span class="art-caption">一期一会 · S56</span></div>
  </section>
  <div v-else class="page-heading"><div><div class="eyebrow dark">SHIKIGAMI ARCHIVE</div><h1>式神图鉴</h1><p>从一个式神开始，读懂它在百炼榜上的表现。</p></div><span class="subtle-tag">已登记 {{ records.length }} 位式神</span></div>
  <section v-if="!catalog" class="metrics" aria-label="当前数据概况">
    <article><span class="metric-icon"><Icon name="cards"/></span><span class="metric-label">已收录式神</span><div class="metric-value">{{ records.length }}<small>位</small></div><span class="metric-note">持续补充式神目录</span></article>
    <article><span class="metric-icon"><Icon name="activity"/></span><span class="metric-label">已有观察的式神</span><div class="metric-value">{{ covered.length }}<small>/ {{ records.length }}</small></div><span class="metric-note"><i class="tiny-dot"></i>{{ sum('observation_count') }} 条真实观察快照</span></article>
    <article><span class="metric-icon"><Icon name="trend"/></span><span class="metric-label">近 7 天新增场数</span><div class="metric-value">{{ sum('sample_games') }}<small>式神对局</small></div><span class="metric-note">有效区间合计 · 非去重比赛数</span></article>
    <article><span class="metric-icon"><Icon name="clock"/></span><span class="metric-label">最近采集</span><div class="metric-value time-value">{{ latest ? date(latest, true).split(' ')[1] : '—' }}</div><span class="metric-note">{{ latest ? date(latest, true).split(' ')[0] + ' · 北京时间' : '等待首次观察' }}</span></article>
  </section>
  <div :class="{ 'overview-grid': !catalog }">
    <section class="panel rankings-panel">
