      <div class="filters"><div class="tabs" role="group" aria-label="观察状态筛选"><button :class="{ selected: filter === 'all' }" @click="filter = 'all'">全部</button><button :class="{ selected: filter === 'observed' }" @click="filter = 'observed'">已观察</button><button :class="{ selected: filter === 'samples' }" @click="filter = 'samples'">有胜率样本</button></div><div class="filter-inputs"><label class="search-field"><Icon name="search" :size="16"/><input v-model="search" aria-label="搜索式神" placeholder="搜索式神"/><button v-if="search" @click="search = ''" aria-label="清空搜索"><Icon name="close" :size="13"/></button></label><select v-model="grade" aria-label="段位筛选"><option value="all">全部段位</option><option value="9">名士</option><option value="10">大名士</option><optgroup label="其他段位"><option v-for="key in [5, 6, 7, 8]" :value="String(key)" :key="key">{{ gradeNames[key] }}</option></optgroup></select></div></div>
